"""Build honest native/art milestone review and portable pixel test manifest."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'development/levels/hollow-creek'
r=json.loads((OUT/'site-art.json').read_text(encoding='utf-8'));f=json.loads((OUT/'siteart-fitted-floors.json').read_text(encoding='utf-8'));v=json.loads((ROOT/'development/levels/verification/hollow-creek-siteart.json').read_text(encoding='utf-8'))
sculpt=json.loads((OUT/'organic-memorial-model.json').read_text(encoding='utf-8'))['asset']
manifest=dict(assets=[a for a in r['assets'] if a['id']!='level_camp_memorial_uv_tracks']+[sculpt]+f['assets'])
(OUT/'siteart-portable-assets.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf-8')
page=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Camp Hollow Creek — site art second pass</title><style>body{background:#171e1c;color:#e6e5d9;font:17px/1.6 system-ui;max-width:1250px;margin:auto;padding:28px}a{color:#b8d6c1}img{width:100%;height:auto}figure{margin:24px 0}.gate{padding:16px;border-left:4px solid #c3a36c;background:#28352e}audio{width:100%}</style><h1>Camp Hollow Creek — site art second pass</h1><p>24 October 2026 · Native scene/model review</p><p class="gate">These are saved native art captures, not running-game screenshots. The map remains locked pending its actual terrain, collision, circuitry, UV encounter and host/LAN integration.</p>']
for name,caption in [('site','Varied tent headings, campsite stones and distant-bank boulders; original terrain and canonical van retained.'),('ground','Two-metre dirty grass and compacted trail tiles; source bitmap originals retained.'),('shore','Actual-height bare pebbly shore and submerged bed: grass stops before the water.'),('memorial','Continuous closed organic casting, seated feet and supported readable plaque.'),('uv-memorial','Manually revealed cosmetic UV layer diagnostic: five outward-face cube marks; this does not demonstrate the runtime trigger.')]:
 filename='siteart-'+name+('-native-diagnostic.png' if name=='uv-memorial' else '-native-fitout.png')
 page.append(f'<figure><img loading="lazy" src="../previews/hollow-creek/{filename}" alt="{html.escape(caption)}"><figcaption>{caption}</figcaption></figure>')
page.append(f'<h2>Actual support and export checks</h2><p>{v["rocks"]} supported stones/boulders, {v["actual_rock_vertex_support_probes"]} actual rock vertex probes, facility clearance, {v["world_scale_uv_loops"]} world-scale UV loops and {v["bare_shore_faces"]} bare-shore faces pass. The casting is one closed connected12002-vertex surface; both feet sit on the plinth. Six site-art exports and eight reoriented/refitted tent exports retain exact oriented source triangles within unchanged 50k-triangle/4MB limits.</p><p>Eight varied tent headings include corresponding bedding relocation and renewed terrain clipping; the original dense floor subdivision is not restored. Independent floor, roof, gear, entry, route, ritual, ramp, culvert and native-barrier checks are retained in linked reports.</p>')
page.append('<h2>Colossal goose audio treatment</h2><audio controls preload="none" src="../../audio/hollow-creek/goose-colossal-omen-v1.wav"></audio><p>Quiet3.195-second pitch-lowered, stretched and wobbling treatment. Source: <a href="https://freesound.org/people/el_boss/sounds/740197/">el_boss — Goose Trumpet (CC0)</a>. Original public HQ preview, filter, hashes and measurements are retained. This asset is not yet connected to an active UV/range/occlusion/host/LAN trigger.</p>')
page.append('<h2>Remaining refinement</h2><p>Continue the environmental material audit through boundary banks, bark, foliage, timber, metal and stone patina. Current tile transitions still follow terrain faces and need a smoother authored blend review. Keep the UV lore cosmetic and distinct from ghost identification evidence. Actual runtime movement/optics/performance, water transparency/layering, electrical behavior, physics, final lore and encounter acceptance remain open.</p>')
for path,label in [('hollow-creek-siteart-fitted.blend','Current native scene'),('site-art.json','Art source packet'),('siteart-fitted-floors.json','Refitted tent placements/exports'),('../verification/hollow-creek-siteart.json','Art/support validation'),('../verification/hollow-creek-siteart-floors.json','Floor/source validation'),('../verification/hollow-creek-siteart-fit.json','Routes/entry/ritual/native barrier validation'),('../verification/hollow-creek-siteart-runtime.json','Game asset loader checks'),('../../audio/hollow-creek/PROVENANCE.json','Audio provenance'),('../textures/hollow-creek/GENERATION_PROMPTS.json','Built-in image-generation source prompts'),('FITTED_FLOOR_REVIEW.html','Previous source milestone'),('../../../beckenburg-development-gallery.html','Shared gallery')]:page.append(f'<p><a href="{path}">{label}</a></p>')
page.append('</html>');(OUT/'SITE_ART_REVIEW.html').write_text('\n'.join(page)+'\n',encoding='utf-8')
banner='<p class="gate"><a href="SITE_ART_REVIEW.html">Latest native review: organic memorial, ground/shore materials, rocks and varied tent headings</a></p>'
for name in ['FITTED_FLOOR_REVIEW.html','EXPANDED_REVIEW.html']:
 p=OUT/name;text=p.read_text(encoding='utf-8')
 if banner not in text:p.write_text(text.replace('<h1>',banner+'<h1>',1),encoding='utf-8')
print('Built native site-art review and13-textured-asset pixel manifest')
